      { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 10413 }, from = { [10413] = { { n = { ko = "송곳니의 드루이드", en = "Druid of the Fang" }, r = 2.34 } } } },
    },
    notes = { { ko = "송곳니의 드루이드는 치유의 손길을 씁니다. 차단을 나눠 맡으세요.", en = "Fanglords heal: assign interrupts." }, { ko = "층이 겹친 동굴입니다. 함부로 뛰어내리면 돌아오기 어렵습니다.", en = "Layered caves: jumping down can split the group." }, { ko = "랩터는 체력이 줄면 주변을 부릅니다. 주변을 비우고 잡으세요.", en = "Raptors call help at low health; clear around first." } },
  },
  {
    key = "dm", slug = "deadmines", levels = "17-26",
    name = { ko = "죽음의 폐광", en = "The Deadmines" },
    instanceIDs = { 36 }, nameMatch = { "죽음의 폐광", "Deadmines" },
    entrance = { map = 1436, x = 38.2, y = 77.5, zone = { ko = "서부 몰락지대 달빛시내 마을 광산 안쪽", en = "Inside the mine at Moonbrook, Westfall" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 644 }, model = 14403, name = { ko = "라크조르", en = "Rhahk'Zor" }, loot = { 273289, 872, 5187 }, tip = { ko = "격돌로 탱커를 기절시킵니다. 기절한 동안 힐러가 체력을 채워 주세요.", en = "Slam stuns the tank; healer tops them up meanwhile." } },
      { id = "s2", n = "2", kind = "rare", optional = true, npc = { 3586 }, model = 556, name = { ko = "광부 존슨", en = "Miner Johnson" }, loot = { 5443, 5444 }, tip = { ko = "옆길 작은 방의 희귀 정예. 건너뛰어도 됩니다.", en = "Rare elite in a side room. Skippable." } },
      { id = "s3", n = "3", kind = "boss", npc = { 643, 642 }, model = 7125, name = { ko = "스니드", en = "Sneed" }, quest = true, loot = { 273293, 5194, 5195, 273092, 1937, 2169, 285292 }, quests = { 2040 }, tip = { ko = "스니드의 벌목기를 먼저 부수면 스니드가 튀어나옵니다. 무장 해제를 씁니다.", en = "Break Sneed's Shredder and he jumps out. He disarms." } },
      { id = "s4", n = "4", kind = "boss", npc = { 1763 }, model = 7124, name = { ko = "길니드", en = "Gilnid" }, quest = true, loot = { 273297, 1156, 5199, 273086 }, quests = { 2040 }, tip = { ko = "용해된 금속을 뿌리고 제련공들이 합류합니다. 쫄부터 정리하세요.", en = "Molten Metal; smelters join the fight. Clear adds first." } },
      { id = "s5", n = "5", kind = "object", name = { ko = "데피아즈단 화약", en = "Defias Gunpowder" }, quest = true, quests = { 92753 }, tip = { ko = "제련소 옆 화약 더미. '죽음의 폐광 파괴 작전'의 폭발물은 이 근처 숨은 가열로에 설치합니다.", en = "Gunpowder by the foundry. Plant the explosives for Destruction in Deadmines at the hidden forge here." } },
      { id = "s6", n = "6", kind = "boss", npc = { 646 }, model = 2026, name = { ko = "미스터 스마이트", en = "Mr. Smite" }, loot = { 284715, 7230, 5192, 5196 }, tip = { ko = "여기부터 배입니다. 체력이 줄면 발구르기로 파티를 기절시키고 상자에서 무기를 바꿉니다. 기절이 풀리면 다시 모이세요.", en = "The ship starts here. At health thresholds he stuns everyone and swaps weapons at his chest; regroup after." } },
      { id = "s7", n = "7", kind = "boss", npc = { 645 }, model = 1305, name = { ko = "쿠키", en = "Cookie" }, loot = { 273298, 5198, 5197, 273102 }, tip = { ko = "갑판 아래 주방. 요리로 자신을 치유하고 산성 물질을 끼얹습니다. 요리를 끊으세요.", en = "Galley below deck. Heals himself by cooking and splashes acid; interrupt the cooking." } },
      { id = "s8", n = "8", kind = "boss", npc = { 647 }, model = 7113, name = { ko = "선장 그린스킨", en = "Captain Greenskin" }, loot = { 5201, 10403, 5200 }, tip = { ko = "독 묻은 작살과 회전베기. 독을 해제하고 탱커 뒤에 서세요.", en = "Poisoned Harpoon and Cleave. Cure poison, stand behind." } },
      { id = "s9", n = "9", kind = "boss", npc = { 639 }, model = 2029, name = { ko = "에드윈 밴클리프", en = "Edwin VanCleef" }, quest = true, loot = { 5193, 5202, 10399, 5191 }, quests = { 166, 373 }, tip = { ko = "배 뒤쪽 윗갑판의 마지막 우두머리. 쌍수 난타, 체력이 줄면 호위병을 부릅니다. 쫄은 묶거나 먼저 잡으세요. '부치지 않은 편지'를 챙기세요.", en = "Final boss on the upper deck aft. Thrash, then calls guards as he weakens; control or kill them. Grab The Unsent Letter." } },
    },
    quests = {
      { id = 214, faction = "Alliance", level = 17, minLevel = 14, name = { ko = "붉은 비단 복면", en = "Red Silk Bandanas" }, giver = { ko = "감시의 언덕 탑의 정찰병 리엘이 붉은 비단 복면 10개를 가져다 달라고 부탁했습니다.", en = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas." } },
      { id = 168, faction = "Alliance", level = 18, minLevel = 14, name = { ko = "기억을 더듬어...", en = "Collecting Memories" }, giver = { ko = "스톰윈드에 있는 빌더 시슬네틀에게 광부 조합의 명함 4장을 가져가야 합니다.", en = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind." } },
      { id = 92753, faction = "Alliance", level = 18, minLevel = 9, name = { ko = "죽음의 폐광 파괴 작전", en = "Destruction in Deadmines" }, giver = { ko = "죽음의 폐광에서 숨겨진 가열로를 찾아 주변에 강력 파괴 폭발물을 설치해야 합니다. 그런 다음 죽음의 폐광 출구에서 알바 페어문을 만나야 합니다.", en = "Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit." } },
      { id = 2040, faction = "Alliance", level = 20, minLevel = 15, name = { ko = "지하 공격", en = "Underground Assault" }, giver = { ko = "죽음의 폐광에서 노암 톱니구동장치를 찾아 스톰윈드에 있는 쇼니에게 가져가야 합니다.", en = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind." } },
      { id = 167, faction = "Alliance", level = 20, minLevel = 15, name = { ko = "형제여...", en = "Oh Brother..." }, giver = { ko = "스톰윈드에 있는 빌더 시슬네틀에게 시슬네틀의 배지를 가져가야 합니다.", en = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind." } },
      { id = 166, faction = "Alliance", level = 22, minLevel = 14, name = { ko = "데피아즈단", en = "The Defias Brotherhood" }, giver = { ko = "에드윈 밴클리프를 처치하고 그 증거로 그의 가면을 그라이언 스타우트맨틀에게 가져가야 합니다.", en = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle." } },
      { id = 373, faction = "Alliance", level = 22, minLevel = 16, name = { ko = "부치지 않은 편지", en = "The Unsent Letter" }, giver = { ko = "스톰윈드에 있는 도시 건축가 바로스 알렉스턴에게 편지를 전달해야 합니다.", en = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind." } },
    },
    trash = { 1934, 10402, 1943, 1951, 10400, 10401, 1929, 1930, 1936, 1944, 1945, 1925 },
    trashGroups = {
      { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 1934, 10402, 1943, 1951, 10400, 10401, 1929, 1930, 1936, 1944, 1945, 1925 }, from = { [1934] = { { n = { ko = "데피아즈단 검은자객", en = "Defias Blackguard" }, r = 6 } }, [10402] = { { n = { ko = "데피아즈단 갱부", en = "Defias Strip Miner" }, r = 3 } }, [1943] = { { n = { ko = "고블린 조선공", en = "Goblin Shipbuilder" }, r = 6 } }, [1951] = { { n = { ko = "데피아즈단 얼음마법사", en = "Defias Squallshaper" }, r = 6 }, { n = { ko = "데피아즈단 해적", en = "Defias Pirate" }, r = 6 } }, [10400] = { { n = { ko = "데피아즈단 작업반장", en = "Defias Taskmaster" }, r = 3 }, { n = { ko = "데피아즈단 감독관", en = "Defias Overseer" }, r = 3 } }, [10401] = { { n = { ko = "데피아즈단 작업반장", en = "Defias Taskmaster" }, r = 3 }, { n = { ko = "데피아즈단 감독관", en = "Defias Overseer" }, r = 3 } }, [1929] = { { n = { ko = "데피아즈단 마술사", en = "Defias Wizard" }, r = 6 }, { n = { ko = "데피아즈단 기원사", en = "Defias Evoker" }, r = 6 } }, [1930] = { { n = { ko = "데피아즈단 광부", en = "Defias Miner" }, r = 3 } }, [1936] = { { n = { ko = "고블린 기술자", en = "Goblin Engineer" }, r = 6 } }, [1944] = { { n = { ko = "고블린 땜장이", en = "Goblin Craftsman" }, r = 5 } }, [1945] = { { n = { ko = "고블린 목공", en = "Goblin Woodcarver" }, r = 7 } }, [1925] = { { n = { ko = "데피아즈단 보초", en = "Defias Watchman" }, r = 7 } } } },
    },
    notes = { { ko = "달빛시내 마을 가는 길에 데피아즈단 정예가 돌아다닙니다. 입구 앞에서 모이세요.", en = "Defias elites roam Moonbrook; meet at the entrance." }, { ko = "밴클리프가 떨구는 '부치지 않은 편지'를 챙기세요.", en = "Loot The Unsent Letter from VanCleef." } },
  },
  {
    key = "rol", slug = "ruins-of-lordaeron", levels = "15-20",
    name = { ko = "로데론의 폐허", en = "Ruins of Lordaeron" },
    instanceIDs = { 2999 }, nameMatch = { "로데론의 폐허", "Ruins of Lordaeron" },
    entrance = { map = 1420, x = 63.3, y = 67.5, zone = { ko = "티리스팔 숲 로데론 폐허 안뜰 동쪽", en = "Eastern courtyard of the Lordaeron ruins, Tirisfal Glades" } },
    steps = {
      { id = "s1", n = "1", kind = "npc", optional = true, name = { ko = "트루먼 대위", en = "Captain Truman" }, quest = true, quests = { 95250 }, tip = { ko = "입구를 나와 바로 왼쪽(북쪽) 벽돌 길의 NPC. 얼라이언스 '흉측한 괴물들'을 주고받습니다(남작의 머리).", en = "Just left (north) of the entrance on the brick path. Alliance quest Abominable Creatures (the Baron's head)." } },
      { id = "s2", n = "2", kind = "boss", name = { ko = "쇠퇴송곳니", en = "Witherfang" }, quest = true, loot = { 271203, 271201, 271202 }, quests = { 95216 }, tip = { ko = "동쪽 거미 구역 넓은 방. 쫄 셋을 달고 긴 복도를 순찰하니, 자리를 비운 사이 남은 무리를 치우세요. 탱커에게 흡혈 독. 호드 '새로운 역병'의 균주.", en = "Big room in the east spider area. Patrols the hallway with three adds; clear while she's away. Leech Poison on the tank. Horde quest item." } },
      { id = "s3", n = "3", kind = "boss", name = { ko = "도살자(남작)", en = "The Butcher(The Baron)" }, quest = true, loot = { 271204, 271205, 271206 }, quests = { 95250, 97288 }, tip = { ko = "게임 안 이름은 '남작'. 거대한 누더기골렘이라 한 방이 아주 셉니다. 탱커 기절·띄우기·전방 베기. 부탱커를 정해 두고 딜러는 어그로 조절.", en = "Shown as The Baron in game. Huge abomination: Knockout stuns the tank, knock-up, cleave. Assign an off-tank; DPS watch threat." } },
      { id = "s7", n = "4", kind = "boss", optional = true, name = { ko = "비열한 빅토르", en = "Viktor the Vile" }, loot = { 271211, 271212, 271218 }, tip = { ko = "남작 다음 남쪽 길을 따라 서쪽 끝 둥근 탑 옆 벽난로로 갑니다. 불을 붙이면 적이 다섯 차례 몰려오고 여섯 번째에 빅토르가 나옵니다. 연속 공세와 강한 근접·흡혈 독에 대비해 체력과 마나를 채우세요. 공세 뒤 등장하지 않는 베타 오류가 보고됐습니다.", en = "After the Baron, follow the southern road west to the fireplace by the round tower. Light it: five waves, then Viktor as the sixth. Top up health/mana for continuous waves, hard melee and Leech Poison. A beta bug can prevent his appearance." } },
      { id = "s4", n = "5", kind = "boss", optional = true, name = { ko = "버려진 자", en = "The Abandoned" }, loot = { 271207, 271208, 271216 }, tip = { ko = "빅토르 벽난로 북동쪽 육각 지붕 건물의 통로를 지나 북쪽 문간으로 갑니다. 문간에 들어서면 세 차례 공세 뒤 네 번째에 나타납니다. 비선공 유령 시민은 건드리지 마세요. 얼음 회오리와 생명력 흡수(차단 가능).", en = "From the fireplace, pass through the hexagon-roofed building to the northeast and go north to the doorway. Three waves, then the Abandoned on the fourth. Leave non-aggressive Ghostly Citizens alone. Frost Nova and interruptible Life Drain." } },
      { id = "s5", n = "6", kind = "boss", name = { ko = "비요크", en = "Bjork" }, loot = { 271209, 271217, 271210 }, tip = { ko = "버려진 자 문간에서 계속 북쪽으로 가면 시장 거리 북서쪽 안개 구역입니다. 거대한 트롤 언데드가 순찰하니 해골·구울 무리를 먼저 정리하세요. 3초 대마법 보호막 동안 시전을 멈추고, 넉백에 대비해 벽을 등지세요.", en = "Continue north from the Abandoned doorway into foggy northwest Market Street. Clear skeletal mages and ghouls while avoiding the roaming undead troll. Hold spells during the 3-second Anti-Magic Shell; tank against a wall for knockback." } },
      { id = "s6", n = "7", kind = "boss", name = { ko = "라스마엘", en = "Rath'mael" }, quest = true, loot = { 271213, 271214, 271215, 273085 }, quests = { 92422 }, tip = { ko = "비요크 다음 남은 구울을 정리하며 연못 동쪽을 따라 남쪽 막다른 곳의 보라색 룬으로 갑니다. 마지막 우두머리를 룬 밖으로 끌어내세요. 불기둥은 차단 순서를 정하고 놓치면 즉시 피하세요.", en = "After Bjork, clear ghouls down the east side of the pools and go south to the purple rune in the dead end. Pull the final boss off the rune. Rotate interrupts for Flamestrike and dodge missed casts." } },
    },
    quests = {
      { id = 95250, faction = "Alliance", level = 21, minLevel = 16, name = { ko = "흉측한 괴물들", en = "Abominable Creatures" }, giver = { ko = "던전에서 남작의 머리(남작의 머리)를 가져와 대장 트루먼에게 전달", en = "Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman." } },
      { id = 92415, faction = "Alliance", level = 22, minLevel = 15, name = { ko = "내가 사랑한다는 걸 기억해", en = "Remember That I Love You" }, giver = { ko = "피로 얼룩진 편지를 스톰윈드에 있는 보육원 원장님 나이팅게일에게 가져가야 합니다.", en = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City." } },
      { id = 95189, faction = "Alliance", level = 22, minLevel = 16, name = { ko = "로데론의 문장", en = "Crest of Lordaeron" }, giver = { ko = "로데론의 문장을 스톰윈드에 있는 귀부인 디나 케네디에게 반환해야 합니다.", en = "Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City." } },
      { id = 95195, faction = "Alliance", level = 22, minLevel = 16, name = { ko = "피투성이 휘장", en = "Bloodied Insignia" }, giver = { ko = "드랍된 피투성이 휘장으로 시작해 10개를 모아 스톰윈드의 장군 마커스 조나단에게", en = "Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City." } },
      { id = 97288, faction = "Horde", level = 21, minLevel = 16, name = { ko = "끝없는 고통", en = "Unending Torment" }, giver = { ko = "흉측한 머리를 언더시티에 있는 누군가에게 전해야 합니다.", en = "Deliver the Abominable Head to someone within the Undercity." } },
      { id = 92401, faction = "Horde", level = 22, minLevel = 15, name = { ko = "두려움에 찬 부탁", en = "A Frightened Request" }, giver = { ko = "로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다.", en = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron." } },
      { id = 92422, faction = "Horde", level = 22, minLevel = 15, name = { ko = "라스마엘의 격노", en = "The Wrath of Rath'mael" }, giver = { ko = "브릴의 죽음경비병 크리스토프를 위해 로데론의 폐허에 있는 라스마엘을 처치해야 합니다.", en = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill." } },
      { id = 95204, faction = "Horde", level = 22, minLevel = 16, name = { ko = "로데론의 문장", en = "Crest of Lordaeron" }, giver = { ko = "던전 안 어딘가에 놓인 로데론의 문장(자리가 고정되지 않음)으로 시작해 언더시티의 오란 스네이크라이스에게", en = "Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity." } },
      { id = 92421, faction = "Horde", level = 22, minLevel = 15, name = { ko = "빛의 정의", en = "Light's Justice" }, giver = { ko = "언더시티에 있는 모빈 라이트베인을 위해 로데론의 폐허에서 온전한 사지 25개를 수집해야 합니다.", en = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity." } },
      { id = 95216, faction = "Horde", level = 22, minLevel = 16, name = { ko = "새로운 역병", en = "The New Plague" }, giver = { ko = "로데론의 폐허에 있는 쇠퇴송곳니에게서 맹독성 균주를 얻어 언더시티에 있는 시어도어 그리프스에게 가져가야 합니다.", en = "Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity." } },
    },
