      { id = "s9", n = "9", kind = "npc", name = { ko = "수입업자 윌릭스", en = "Willix the Importer" }, quest = true, quests = { 1142, 1144, 1221 }, tip = { ko = "갇혀 있는 윌릭스. 입구까지 호위하면 퀘스트 완료. 청엽수 줄기 자리도 이 근처에 많습니다.", en = "Willix is held here; escort him to the entrance. Many Blueleaf Tuber spots nearby." } },
