      { id = "s11", n = "11", kind = "boss", npc = { 4421 }, model = 4642, name = { ko = "서슬깃 차를가", en = "Charlga Razorflank" }, quest = true, loot = { 6692, 6693, 6694, 17008 }, quests = { 1101, 1102 }, tip = { ko = "연쇄 벼락·마나 쐐기, 소생으로 회복. 흩어져 서고 소생을 해제하세요. 퀘스트용 메달·심장을 떨굽니다.", en = "Chain Bolt, Mana Spike, heals with Renew. Spread out and dispel Renew. Drops quest medallion/heart." } },
